#include <cuda_fp16.h>

__global__ void cumulative_product_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride
) {
    int64_t batch_idx = blockIdx.x;
    int64_t thread_idx = threadIdx.x;

    if (batch_idx >= total_elements / dim_size) return;

    // Each thread processes one element in the current batch
    for (int64_t i = thread_idx; i < dim_size; i += blockDim.x) {
        int64_t base_offset = batch_idx * dim_size;
        int64_t output_offset = base_offset + i;

        if (i == 0) {
            output[output_offset] = input[output_offset];
        } else {
            int64_t prev_offset = base_offset + i - 1;
            output[output_offset] = __hmul(output[prev_offset], input[output_offset]);
        }
    }
}

__global__ void cumulative_product_kernel_2d(
    const half* input,
    half* output,
    int64_t rows,
    int64_t cols,
    int64_t dim
) {
    if (dim == 1) {
        // Cumulative product along columns (dim=1)
        int64_t row = blockIdx.x * blockDim.x + threadIdx.x;
        if (row >= rows) return;

        half accum = __float2half(1.0f);
        for (int64_t col = 0; col < cols; col++) {
            int64_t idx = row * cols + col;
            if (col == 0) {
                output[idx] = input[idx];
                accum = input[idx];
            } else {
                accum = __hmul(accum, input[idx]);
                output[idx] = accum;
            }
        }
    } else if (dim == 0) {
        // Cumulative product along rows (dim=0)
        int64_t col = blockIdx.x * blockDim.x + threadIdx.x;
        if (col >= cols) return;

        half accum = __float2half(1.0f);
        for (int64_t row = 0; row < rows; row++) {
            int64_t idx = row * cols + col;
            if (row == 0) {
                output[idx] = input[idx];
                accum = input[idx];
            } else {
                accum = __hmul(accum, input[idx]);
                output[idx] = accum;
            }
        }
    }
}

// Main kernel launcher
void launch_cumulative_product(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t dim
) {
    if (dim == 1) {
        int64_t rows = total_elements / dim_size;
        int64_t cols = dim_size;

        // Use 2D kernel for better performance on A100
        dim3 block_size(256);
        dim3 grid_size((rows + block_size.x - 1) / block_size.x);

        cumulative_product_kernel_2d<<<grid_size, block_size>>>(
            input, output, rows, cols, dim
        );
    } else {
        // For other dimensions, use simple approach
        int64_t batch_size = total_elements / dim_size;
        dim3 block_size(256);
        dim3 grid_size((batch_size + block_size.x - 1) / block_size.x);

        cumulative_product_kernel<<<grid_size, block_size>>>(
            input, output, total_elements, dim_size, stride
        );
    }
}
